{
  "name": "@kontourai/ferry",
  "version": "0.8.0",
  "description": "Migrate AI conversations between tools — importers and exporters for @kontourai/thread",
  "license": "Apache-2.0",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/src/index.d.ts",
      "default": "./dist/src/index.js"
    }
  },
  "bin": {
    "ferry": "dist/src/cli.js"
  },
  "files": [
    "dist/src/",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "ai",
    "conversation",
    "migration",
    "import",
    "export",
    "claude-code",
    "codex",
    "opencode",
    "chatgpt"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/kontourai/thread.git",
    "directory": "packages/ferry"
  },
  "engines": {
    "node": ">=22"
  },
  "dependencies": {
    "@kontourai/thread": "^0.7.0",
    "commander": "^15.0.0",
    "zod": "^4.6.7"
  },
  "devDependencies": {
    "@types/node": "^26.6.5",
    "typescript": "^7.0.2",
    "vitest": "^5.0.5"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "rm -rf dist && tsc && chmod +x dist/src/cli.js",
    "typecheck": "tsc -p tsconfig.typecheck.json",
    "test": "npm run build && vitest run"
  }
}
